using System.Collections.ObjectModel;using System.Windows.Input;using WAID.Application.Abstractions;using WAID.Infrastructure.Diagnostics;namespace WAID.Desktop.ViewModels;public sealed class SecurityCenterViewModel:ViewModelBase{private readonly ISecurityPostureAnalyzer _a;private readonly ISecurityPostureRepository _r;private readonly AsyncCommand _run;private bool _init;private string _status="Select Analyze security posture to inspect Windows controls.";public SecurityCenterViewModel(ISecurityPostureAnalyzer a,ISecurityPostureRepository r){_a=a;_r=r;_run=new(Run);}public ObservableCollection<SecurityControlStatus> Controls{get;}=[];public ObservableCollection<SecurityFinding> Findings{get;}=[];public ICommand AnalyzeCommand=>_run;public string Status{get=>_status;private set=>Set(ref _status,value);}public async Task InitializeAsync(){if(_init)return;_init=true;var x=await _r.GetLatestAsync(CancellationToken.None);if(x is not null)Fill(x);}private async Task Run(){Status="Collecting supported Windows security posture evidence…";try{var x=await _a.AnalyzeAsync(CancellationToken.None);Fill(x);Status=$"Reviewed {x.Controls.Count} controls. Unknown or unavailable controls are not shown as disabled.";}catch(SecurityPostureException e){Status=$"Security posture unavailable ({e.Code}): {e.Message}";}}private void Fill(SecurityPostureReport x){Controls.Clear();Findings.Clear();foreach(var c in x.Controls)Controls.Add(c);foreach(var f in x.Findings)Findings.Add(f);}}
